print(f"Loaded {len(HINDI_DATA)} words in HINDI_DATA")

with open("index.html", "r", encoding="utf-8") as f:
    content = f.read()

tier_names = [
    "tier1_200DeckCards", "tier201DeckCards", "tier401DeckCards", "tier601DeckCards", "initialDeckCards",
    "tier1001DeckCards", "tier1201DeckCards", "tier1401DeckCards", "tier1601DeckCards", "tier1801DeckCards",
    "tier2001DeckCards", "tier2501DeckCards", "tier1DeckCards", "tier101DeckCards"
]

fixed_count = 0

for name in tier_names:
    prefix = f"var {name} = "
    start_idx = content.find(prefix)
    if start_idx == -1:
        continue
    json_start = start_idx + len(prefix)
    end_idx = content.find(";\n", json_start)
    if end_idx == -1:
        continue
    
    cards = json.loads(content[json_start:end_idx])
    modified = False

    for c in cards:
        word = c.get("word", "").strip().upper()
        if word in HINDI_DATA:
            hi_trans, hi_dev, hi_m = HINDI_DATA[word]
            if "trans" not in c:
                c["trans"] = {}
            c["trans"]["hi"] = hi_trans
            c["hiDevanagari"] = hi_dev
            c["shortcutHi"] = f"<strong>{hi_dev} ({hi_trans})</strong> → {hi_m} = <em>{word}</em>!"
            fixed_count += 1
            modified = True

    if modified:
        new_json = json.dumps(cards, ensure_ascii=False)
        content = content[:json_start] + new_json + content[end_idx:]
        print(f"Updated {name}")

with open("index.html", "w", encoding="utf-8") as f:
    f.write(content)

print(f"Enrichment complete! Fixed {fixed_count} card occurrences.")
